with parsed as (select id, array_min(tier_prices) as lowest_price, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, element_at(tier_prices, 1) as entry_price from price_tiers) select id, entry_price, max(avg_tier_price) over (order by avg_tier_price, id rows between 2 preceding and current row) last3_max_avg_tier_price, sum(avg_tier_price) over (order by avg_tier_price, id rows between 2 preceding and current row) last3_sum_avg_tier_price, count(avg_tier_price) over (order by avg_tier_price, id rows between 2 preceding and current row) last3_count_avg_tier_price, ntile(3) over (order by lowest_price desc, id) lowest_price_bucket from parsed where lowest_price <= 21
